      controller.abort();
      await expect(blocked).rejects.toMatchObject({ name: 'AbortError' });
      await vi.advanceTimersByTimeAsync(1_000);
      expect(await limiter.run(async () => 'ready')).toBe('ready');
    } finally {
      vi.useRealTimers();
    }
  });
});


