    var selector = mode === 'playback-stable-id' ? '#' + element.id : selectorFor(element);
    if (mode === 'playback-stable-id') {
      selectedSelector = selector;
      selectedHandle = element;
      invalidSelectedSelector = null;
      var pickedMode = mode;
